<div><p class="eyebrow">MANAGEMENT</p><h2><?=$title?></h2><section class="panel"><table class="table"><tr><th>Client</th><th>Email</th><th>Details</th><th>Status</th><th>Submitted</th><th>Action</th></tr><?php if(empty($rows)):?><tr><td colspan="6" style="text-align:center;color:#8993a8;padding:35px">No records to display.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td><?=html_escape($row['first_name'].' '.$row['last_name'])?></td><td><?=html_escape($row['email'])?></td><td><?php if($type==='loans'):?>$<?=number_format($row['amount'],2)?> / <?=$row['term_months']?> months<?php elseif($type==='cards'||$type==='card-applications'):?><?=ucfirst($row['card_type'])?> · •••• <?=$row['last_four']?><?php else:?><?=html_escape($row['document_type']??'—')?></td><?php endif;?></td><td><span class="badge <?=$row['status']?>"><?=$row['status']?></span></td><td><?=date('M j, Y',strtotime($row['created_at']))?></td><td><a class="button small" href="#">Review</a></td></tr><?php endforeach;?></table></section></div>
